sp_widget.css:
.hod-cases-page {
  max-width: 1180px;
  margin: 30px auto;
  padding: 0 20px 50px;
  color: #0f1b45;
}


/* ==================================================
   PAGE HEADER
   ================================================== */

.page-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}

.page-header h2 {
  margin: 0 0 6px;
  font-size: 28px;
  font-weight: 700;
  color: #0f1b45;
}

.page-header p {
  margin: 0;
  color: #7b8497;
  font-size: 13px;
  line-height: 1.5;
}

.back-link {
  color: #1769e0 !important;
  text-decoration: none !important;
  font-size: 13px;
  white-space: nowrap;
}

.back-link:hover {
  text-decoration: underline !important;
}


/* ==================================================
   MESSAGE
   ================================================== */

.hod-message {
  padding: 13px 15px;
  border-radius: 9px;
  margin-bottom: 18px;
  font-size: 13px;
}

.hod-message.error {
  background: #fdeaea;
  border: 1px solid #efc2c0;
  color: #b42318;
}


/* ==================================================
   SUMMARY CARDS
   ================================================== */

.summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 20px;
}

.summary-card {
  background: #fff;
  border: 1px solid #e2e7ef;
  border-radius: 12px;
  padding: 18px;
  box-shadow: 0 3px 10px rgba(20, 40, 80, .04);
}

.summary-card span {
  display: block;
  color: #7b8497;
  font-size: 13px;
  margin-bottom: 8px;
}

.summary-card strong {
  font-size: 24px;
  color: #0f1b45;
}


/* ==================================================
   CASES CARD
   ================================================== */

.cases-card {
  background: #fff;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 3px 10px rgba(0,0,0,.04);
}

.table-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  margin-bottom: 16px;
}

.table-header h3 {
  margin: 0 0 4px;
  font-size: 20px;
  color: #0f1b45;
}

.table-header span {
  display: inline-block;
  color: #8a93a5;
  font-size: 12px;
  margin-bottom: 3px;
}

.table-header p {
  margin: 3px 0 0;
  color: #8a93a5;
  font-size: 11px;
}


/* ==================================================
   SEARCH
   ================================================== */

.search-wrapper {
  width: 250px;
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #dce2eb;
  border-radius: 8px;
  padding: 0 11px;
  background: #ffffff;
}

.search-icon {
  font-size: 12px;
  color: #8a93a5;
}

.search-box {
  width: 100%;
  border: none;
  padding: 10px 0;
  outline: none;
  background: transparent;
  font-size: 12px;
  color: #263250;
}


/* ==================================================
   TABLE
   ================================================== */

.table-responsive {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

thead {
  background: #f6f8fb;
}

th {
  padding: 13px 10px;
  text-align: left;
  font-size: 12px;
  font-weight: 700;
  color: #35405b;
  white-space: nowrap;
}

td {
  padding: 14px 10px;
  border-bottom: 1px solid #edf0f4;
  font-size: 13px;
  color: #293551;
  vertical-align: middle;
}

tbody tr:hover {
  background: #fafbfe;
}

.case-number {
  color: #0f1b45;
}


/* ==================================================
   STATUS / PRIORITY BADGES
   ================================================== */

.status-badge,
.priority-badge {
  display: inline-block;
  border-radius: 20px;
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}


/* STATUS */

.status-open {
  background: #fff3d8;
  color: #9a6500;
}

.status-in_progress {
  background: #e5f0ff;
  color: #1769aa;
}

.status-awaiting_employee_confirmation {
  background: #fff4d6;
  color: #a35d00;
}

.status-resolved {
  background: #e4f7ee;
  color: #15724f;
}

.status-closed {
  background: #edf0f4;
  color: #596273;
}


/* PRIORITY */

.priority-high {
  background: #ffe8e8;
  color: #b42318;
}

.priority-medium {
  background: #fff3d8;
  color: #946200;
}

.priority-low {
  background: #e5f0ff;
  color: #1769aa;
}


/* ==================================================
   VIEW CASE BUTTON
   ================================================== */

.view-case-btn {
  display: inline-block;
  padding: 7px 14px;
  border-radius: 7px;
  background: #0b8793;
  color: #ffffff !important;
  text-decoration: none !important;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: .2s;
  white-space: nowrap;
}

.view-case-btn:hover {
  background: #076f78;
  color: #ffffff !important;
  text-decoration: none !important;
}


/* ==================================================
   MUTED TEXT
   ================================================== */

.muted-text {
  color: #929aac;
  font-style: italic;
}


/* ==================================================
   EMPTY STATE
   ================================================== */

.empty-state {
  text-align: center;
  padding: 35px;
  color: #8a93a5;
}

.empty-icon {
  font-size: 40px;
  margin-bottom: 10px;
}

.empty-state h3 {
  margin: 0 0 6px;
  color: #0f1b45;
  font-size: 17px;
}

.empty-state p {
  margin: 0;
  font-size: 12px;
  line-height: 1.6;
}


/* ==================================================
   RESPONSIVE
   ================================================== */

@media (max-width: 900px) {

  .summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

}


@media (max-width: 800px) {

  .page-header,
  .table-header {
    display: block;
  }

  .back-link {
    display: inline-block;
    margin-top: 12px;
  }

  .search-wrapper {
    width: 100%;
    margin-top: 14px;
  }

}


@media (max-width: 600px) {

  .hod-cases-page {
    margin-top: 20px;
    padding: 0 14px 40px;
  }

  .summary-grid {
    grid-template-columns: 1fr;
  }

  .page-header h2 {
    font-size: 24px;
  }

}

sp_widget.script:
(function() {

    // ----------------------------------
    // INITIAL DATA
    // ----------------------------------

    data.departmentName = "";
    data.departmentCode = "";

    data.cases = [];

    data.totalCount = 0;
    data.openCount = 0;
    data.inProgressCount = 0;
    data.resolvedCount = 0;

    data.error = false;
    data.message = "";

    var departmentId = "";


    // ----------------------------------
    // 1. GET LOGGED-IN HOD DEPARTMENT
    // ----------------------------------

    var userGR =
        new GlideRecord('sys_user');

    if (userGR.get(gs.getUserID())) {

        departmentId =
            userGR.getValue(
                'department'
            ) || "";

        data.departmentName =
            userGR.getDisplayValue(
                'department'
            ) || "";
    }


    if (!departmentId) {

        data.error = true;

        data.message =
            "No department is associated with the logged-in HOD.";

        return;
    }


    // ----------------------------------
    // 2. GET DEPARTMENT CODE
    // ----------------------------------

    var deptGR =
        new GlideRecord(
            'cmn_department'
        );

    if (deptGR.get(departmentId)) {

        data.departmentCode =
            deptGR.getValue('id') || "";
    }


    // ----------------------------------
    // 3. GET HR CASES FROM SAME DEPARTMENT
    //
    // HR Case
    //   -> Request By
    //   -> User
    //   -> Department
    // ----------------------------------

    var caseGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );


    caseGR.addQuery(
        'request_by.department',
        departmentId
    );


	caseGR.addQuery(
		'request_by',
		'!=',
		gs.getUserID()
	);


    caseGR.orderByDesc(
        'sys_created_on'
    );


    caseGR.query();


    while (caseGR.next()) {


        // ----------------------------------
        // STATUS
        // ----------------------------------

        var statusValue =
            caseGR.getValue(
                'status'
            ) || "";


        var statusLabel =
            caseGR.getDisplayValue(
                'status'
            ) || "";


        // Friendly label for custom status
        if (
            statusValue ==
            'awaiting_employee_confirmation'
        ) {

            statusLabel =
                'Awaiting Employee Confirmation';
        }


        // ----------------------------------
        // PRIORITY
        // ----------------------------------

        var priorityValue =
            caseGR.getValue(
                'priority'
            ) || "";


        // ----------------------------------
        // COUNTERS
        // ----------------------------------

        data.totalCount++;


        if (statusValue == 'open') {

            data.openCount++;

        }

        else if (
            statusValue == 'in_progress'
        ) {

            data.inProgressCount++;

        }

        else if (
            statusValue == 'resolved'
        ) {

            data.resolvedCount++;
        }


        // ----------------------------------
        // CREATED DATE
        // ----------------------------------

        var createdOn =
            caseGR.getDisplayValue(
                'created_on'
            );


        if (!createdOn) {

            createdOn =
                caseGR.getDisplayValue(
                    'sys_created_on'
                );
        }


        // ----------------------------------
        // PUSH CASE DATA
        // ----------------------------------

        data.cases.push({

            // Required for View button
            sys_id:
                caseGR.getUniqueValue(),

            number:
                caseGR.getDisplayValue(
                    'number'
                ),

            requestedBy:
                caseGR.getDisplayValue(
                    'request_by'
                ),

            category:
                caseGR.getDisplayValue(
                    'category'
                ),

            priority:
                caseGR.getDisplayValue(
                    'priority'
                ),

            priorityValue:
                priorityValue,

            assignmentGroup:
                caseGR.getDisplayValue(
                    'assignment_group'
                ) || "",

            assignedTo:
                caseGR.getDisplayValue(
                    'assigned_to'
                ) || "",

            status:
                statusLabel,

            statusValue:
                statusValue,

            createdOn:
                createdOn

        });
    }

})();
